cat > /workspace/src/app.rs << 'EOF'
use std::path::Path;
use anyhow::Result;
use arrow::array::RecordBatch;
use crate::parquet_reader::{self, ParquetData};

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Tab {
    Visualize,
    Metadata,
    Schema,
    RowGroups,
}

pub struct App {
    pub current_tab: Tab,
    pub data: ParquetData,
    pub row_offset: usize,
    pub col_offset: usize,
    pub selected_row: usize,
    pub selected_col: usize,
}

impl App {
    pub fn new(path: &Path) -> Result<Self> {
        let data = parquet_reader::read_parquet(path)?;

        Ok(Self {
            current_tab: Tab::Visualize,
            data,
            row_offset: 0,
            col_offset: 0,
            selected_row: 0,
            selected_col: 0,
        })
    }

    pub fn next_tab(&mut self) {
        self.current_tab = match self.current_tab {
            Tab::Visualize => Tab::Metadata,
            Tab::Metadata => Tab::Schema,
            Tab::Schema => Tab::RowGroups,
            Tab::RowGroups => Tab::Visualize,
        };
    }

    pub fn move_up(&mut self) {
        if self.selected_row > 0 {
            self.selected_row -= 1;
            if self.selected_row < self.row_offset {
                self.row_offset = self.selected_row;
            }
        }
    }

    pub fn move_down(&mut self) {
        if self.selected_row < self.data.file_metadata.num_rows as usize - 1 {
            self.selected_row += 1;
            let visible_rows = 15; // Approximate
            if self.selected_row >= self.row_offset + visible_rows {
                self.row_offset = self.selected_row - visible_rows + 1;
            }
        }
    }

    pub fn move_left(&mut self) {
        if self.selected_col > 0 {
            self.selected_col -= 1;
            if self.selected_col < self.col_offset {
                self.col_offset = self.selected_col;
            }
        }
    }

    pub fn move_right(&mut self) {
        if let Some(batch) = self.data.batches.first() {
            if self.selected_col < batch.num_columns() - 1 {
                self.selected_col += 1;
                let visible_cols = 8; // Approximate
                if self.selected_col >= self.col_offset + visible_cols {
                    self.col_offset = self.selected_col - visible_cols + 1;
                }
            }
        }
    }

    pub fn page_up(&mut self) {
        let page_size = 10;
        if self.row_offset >= page_size {
            self.row_offset -= page_size;
            self.selected_row = self.row_offset;
        } else {
            self.row_offset = 0;
            self.selected_row = 0;
        }
    }

    pub fn page_down(&mut self) {
        let page_size = 10;
        let total_rows = self.data.file_metadata.num_rows as usize;
        if self.row_offset + page_size < total_rows {
            self.row_offset += page_size;
            self.selected_row = self.row_offset;
        }
    }
}
EOF

