fn format_array_value(col: &arrow::array::ArrayRef, idx: usize) -> String {
    use arrow::array::{Array, BooleanArray, Int32Array, Int64Array, Float32Array, Float64Array, StringArray, BinaryArray, TimestampNanosecondArray};

    if idx >= col.len() {
        return String::new();
    }

    if col.is_null(idx) {
        return "NULL".to_string();
    }

    let val = if let Some(arr) = col.as_any().downcast_ref::<Int32Array>() {
        arr.value(idx).to_string()
    } else if let Some(arr) = col.as_any().downcast_ref::<Int64Array>() {
