fn format_size(label: &str, bytes: u64) -> String {
    if bytes < 1024 {
        format!("{:>20} {} B", label, bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:>20} {:.2} KiB", label, bytes as f64 / 1024.0)
    } else {
        format!("{:>20} {:.2} MiB", label, bytes as f64 / (1024.0 * 1024.0))
    }
}

fn create_centered_block(area: Rect, width: u16, height: u16) -> Rect {
    let h_offset = (area.width - width) / 2;
    let v_offset = (area.height - height) / 2;

    Rect {
        x: area.x + h_offset,
        y: area.y + v_offset,
        width: width.min(area.width),
        height: height.min(area.height),
    }
}
