fn draw_visualize_tab<B: Backend>(f: &mut ratatui::Frame<B>, area: Rect, app: &App) {
    if app.data.batches.is_empty() {
        return;
    }

    let batch = &app.data.batches[0];

    // Draw data table
    let mut lines = Vec::new();

    // Header row
    let mut header_spans = vec![Span::raw("      ")]; // Row number column
    for col_idx in app.col_offset..batch.num_columns() {
        if col_idx > app.col_offset && col_idx - app.col_offset < 10 {
            header_spans.push(Span::raw("  "));
        }
        if col_idx - app.col_offset >= 10 {
            break;
        }
        let name = batch.schema().field(col_idx).name();
        header_spans.push(Span::raw(name.to_string()));
    }
    lines.push(Line::from(header_spans));

    // Separator
    let sep = "──────┬".to_string() + &"─".repeat(100);
    lines.push(Line::from(Span::raw(sep)));

    // Data rows
    let num_rows = batch.num_rows();
    for row_idx in app.row_offset..std::cmp::min(app.row_offset + 15, num_rows) {
        let mut row_spans = vec![];

        // Row number
        row_spans.push(Span::raw(format!("{:<6}│", row_idx + 1)));

        // Row data
        for col_idx in app.col_offset..batch.num_columns() {
            if col_idx - app.col_offset >= 10 {
                break;
            }

            let col = batch.column(col_idx);
            let value_str = format_array_value(col, row_idx);
            row_spans.push(Span::raw(format!("  {:<20}", value_str)));
        }

        lines.push(Line::from(row_spans));
    }

    let block = Block::default().borders(Borders::NONE);
    let p = Paragraph::new(lines).block(block).wrap(Wrap { trim: false });
    f.render_widget(p, area);
}

fn draw_metadata_tab<B: Backend>(f: &mut ratatui::Frame<B>, area: Rect, app: &App) {
    let meta = &app.data.file_metadata;

    let compression_ratio = if meta.raw_size > 0 {
        meta.compressed_size as f64 / meta.raw_size as f64
    } else {
        0.0
    };

    let codec_str = if app.data.row_group_metadatas.is_empty() {
        "UNCOMPRESSED(0)".to_string()
    } else {
        "UNCOMPRESSED(11)".to_string() // Placeholder
    };

    let mut content = vec![
        Line::from(format!("    Format version {}", meta.version)),
        Line::from(format!("        Created by {}", meta.created_by)),
        Line::from(format!("              Rows {}", meta.num_rows)),
        Line::from(format!("           Columns {}", meta.num_columns)),
        Line::from(format!("        Row groups {}", meta.num_row_groups)),
        Line::from(format_size("        Size (raw)", meta.raw_size)),
        Line::from(format_size(" Size (compressed)", meta.compressed_size)),
        Line::from(format!(
            " Compression ratio {:.2}x",
            compression_ratio
        )),
        Line::from(format!("     Codecs (cols) {}", codec_str)),
        Line::from("         Encodings PLAIN, PLAIN_DICTIONARY, RLE"),
        Line::from(format!(
            "      Avg row size {} B",
            if meta.num_rows > 0 {
                meta.raw_size / meta.num_rows as u64
            } else {
                0
            }
        )),
    ];

    let centered_block = create_centered_block(area, 60, 11);
    let p = Paragraph::new(content)
        .block(Block::default().borders(Borders::ALL).title("File Metadata"))
        .alignment(Alignment::Left);

    f.render_widget(p, centered_block);
}

fn draw_schema_tab<B: Backend>(f: &mut ratatui::Frame<B>, area: Rect, app: &App) {
    if app.data.batches.is_empty() {
        return;
    }

    let batch = &app.data.batches[0];
    let schema = batch.schema();

    // Left panel - schema tree
    let tree_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(25), Constraint::Percentage(75)])
        .split(area);

    let mut tree_lines = vec![Line::from("└─ root")];
    for field_idx in 0..schema.fields().len() {
        let field = schema.field(field_idx);
        let is_last = field_idx == schema.fields().len() - 1;
        let prefix = if is_last { "└─ " } else { "├─ " };
        tree_lines.push(Line::from(format!("   {}{}", prefix, field.name())));
    }

    let tree_widget = Paragraph::new(tree_lines)
        .block(Block::default().borders(Borders::RIGHT).title("Schema Tree"))
        .wrap(Wrap { trim: false });

    f.render_widget(tree_widget, tree_chunks[0]);

    // Right panel - column statistics
    let mut stat_lines = vec![
        Line::from("Repetition  Physical    Compressed  Uncompressed  Ratio  Encodings                     Compression   Min   Max   Nulls"),
    ];

    for field_idx in 0..schema.fields().len() {
        let field = schema.field(field_idx);
        let data_type = field.data_type();
        let type_str = format!("{:?}", data_type);
        stat_lines.push(Line::from(format!(
            "OPTIONAL    {}                                    UNCOMPRESSED  NULL  NULL  0",
            type_str
        )));
    }

    let stat_widget = Paragraph::new(stat_lines)
        .block(Block::default().borders(Borders::NONE).title("Column Statistics"))
        .wrap(Wrap { trim: false });

    f.render_widget(stat_widget, tree_chunks[1]);
}

fn draw_row_groups_tab<B: Backend>(f: &mut ratatui::Frame<B>, area: Rect, app: &App) {
    if app.data.row_group_metadatas.is_empty() {
        return;
    }

    let rg = &app.data.row_group_metadatas[0];

    let mut content = vec![
        Line::from(format!("Row Group: 1 / {}", app.data.file_metadata.num_row_groups)),
        Line::from("█".repeat(150)),
        Line::from(""),
        Line::from("Rows"),
        Line::from(format!("{}", rg.num_rows)),
        Line::from(""),
        Line::from("Compressed vs Uncompressed (B)"),
    ];

    let p = Paragraph::new(content)
        .block(Block::default().borders(Borders::NONE))
        .wrap(Wrap { trim: false });

    f.render_widget(p, area);
}

fn format_array_value(col: &arrow::array::ArrayRef, idx: usize) -> String {
    use arrow::array::{Array, BooleanArray, Int32Array, Int64Array, Float32Array, Float64Array, StringArray, BinaryArray, TimestampNanosecondArray};

    if idx >= col.len() {
        return String::new();
    }

    if col.is_null(idx) {
        return "NULL".to_string();
    }

    let val = if let Some(arr) = col.as_any().downcast_ref::<Int32Array>() {
        arr.value(idx).to_string()
    } else if let Some(arr) = col.as_any().downcast_ref::<Int64Array>() {
        arr.value(idx).to_string()
    } else if let Some(arr) = col.as_any().downcast_ref::<Float32Array>() {
        arr.value(idx).to_string()
    } else if let Some(arr) = col.as_any().downcast_ref::<Float64Array>() {
        arr.value(idx).to_string()
    } else if let Some(arr) = col.as_any().downcast_ref::<BooleanArray>() {
        arr.value(idx).to_string()
    } else if let Some(arr) = col.as_any().downcast_ref::<StringArray>() {
        arr.value(idx).to_string()
    } else if let Some(arr) = col.as_any().downcast_ref::<BinaryArray>() {
        let bytes = arr.value(idx);
        format!("b\"{:?}\"", String::from_utf8_lossy(bytes))
    } else {
        format!("{:?}", col.data_type())
    };

    if val.len() > 20 {
        format!("{}…", &val[..17])
    } else {
        val
    }
}

fn format_size(label: &str, bytes: u64) -> String {
    if bytes < 1024 {
        format!("{:>20} {} B", label, bytes)
    } else if bytes < 1024 * 1024 {
        format!("{:>20} {:.2} KiB", label, bytes as f64 / 1024.0)
    } else {
        format!("{:>20} {:.2} MiB", label, bytes as f64 / (1024.0 * 1024.0))
    }
}

fn create_centered_block(area: Rect, width: u16, height: u16) -> Rect {
    let h_offset = (area.width - width) / 2;
    let v_offset = (area.height - height) / 2;

    Rect {
        x: area.x + h_offset,
        y: area.y + v_offset,
        width: width.min(area.width),
        height: height.min(area.height),
    }
}
