use std::collections::HashMap;
use std::io::{Cursor, Read};

pub struct ParquetData {
    pub rows: Vec<Vec<String>>,
    pub columns: Vec<String>,
    pub metadata: FileMetadata,
    pub raw_data: Vec<u8>,
}

pub struct FileMetadata {
    pub created_by: String,
    pub num_rows: i64,
    pub num_columns: usize,
    pub num_row_groups: usize,
    pub version: i32,
    pub raw_size: u64,
    pub compressed_size: u64,
}

pub fn parse(data: &[u8]) -> Result<ParquetData, String> {
    if data.len() < 12 {
        return Err("Invalid parquet file: too small".to_string());
    }

    // Check magic number at start
    if &data[0..4] != b"PAR1" {
        return Err("Invalid parquet file: missing PAR1 header".to_string());
    }

    // Check magic number at end  
    if &data[data.len()-4..] != b"PAR1" {
        return Err("Invalid parquet file: missing PAR1 footer".to_string());
    }

    // Parse footer metadata size (4 bytes before the final PAR1)
    let footer_size_pos = data.len() - 8;
    let footer_size = u32::from_le_bytes([
        data[footer_size_pos],
        data[footer_size_pos + 1],
        data[footer_size_pos + 2],
        data[footer_size_pos + 3],
    ]) as usize;

    if footer_size > data.len() - 8 {
        return Err("Invalid footer size".to_string());
    }

    let metadata_start = data.len() - 8 - footer_size;
    let _metadata_bytes = &data[metadata_start..data.len()-8];

    // Try to parse basic structure
    // Look for column chunks in the data
    let mut columns = Vec::new();
    let mut rows = Vec::new();
    let mut num_rows = 0i64;

    // Simple heuristic: look for printable ASCII strings that might be column names
    let mut i = 4; // Skip initial PAR1
    while i < metadata_start.saturating_sub(100) {
        if let Some((col_name, name_len)) = try_read_string(&data[i..]) {
            if col_name.len() > 0 && col_name.len() < 100 && is_reasonable_column_name(&col_name) {
                columns.push(col_name);
                i += name_len;
            } else {
                i += 1;
            }
        } else {
            i += 1;
        }
    }

    if columns.is_empty() {
        columns.push("column".to_string());
    }

    Ok(ParquetData {
        rows,
        columns,
        metadata: FileMetadata {
            created_by: "".to_string(),
            num_rows,
            num_columns: columns.len(),
            num_row_groups: 1,
            version: 1,
            raw_size: data.len() as u64,
            compressed_size: data.len() as u64,
        },
        raw_data: data.to_vec(),
    })
}

fn try_read_string(data: &[u8]) -> Option<(String, usize)> {
    // Try to read a length-prefixed or null-terminated string
    if data.len() < 1 {
        return None;
    }

    // Look for null-terminated string
    for i in 0..data.len().min(200) {
        if data[i] == 0 {
            let s = String::from_utf8(data[0..i].to_vec()).ok()?;
            if s.len() > 0 {
                return Some((s, i + 1));
            }
            break;
        }
    }

    None
}

fn is_reasonable_column_name(name: &str) -> bool {
    // Column names should be printable ASCII and not too long
    name.chars().all(|c| (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '-')
}
