    let args: Vec<String> = env::args().collect();

    // Check for version and help flags
    if args.len() > 1 {
        match args[1].as_str() {
            "--help" | "-h" => {
                print_help();
                return;
            }
            "--version" | "-V" => {
                println!("parqeye 0.0.2");
                return;
