mod parquet;
mod tui;

fn main() {
    let args: Vec<String> = env::args().collect();

    // Check for version and help flags
    if args.len() > 1 {
        match args[1].as_str() {
            "--help" | "-h" => {
                print_help();
                return;
            }
            "--version" | "-V" => {
                println!("parqeye 0.0.2");
                return;
            }
            _ => {}
        }
    }

    // Check if we have exactly one argument (the path)
    if args.len() != 2 {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <PATH>");
        eprintln!();
        eprintln!("Usage: {} <PATH>", args.get(0).unwrap_or(&"executable".to_string()));
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }

    let path = &args[1];

    // Check if file exists
    if !fs::metadata(path).is_ok() {
        eprintln!("Error: Custom {{ kind: Other, error: \"No such file or directory (os error 2)\" }}");
        process::exit(101);
    }

    // Read the file
    match fs::read(path) {
        Ok(data) => {
            match parquet::parse(&data) {
                Ok(parquet_data) => {
                    if let Err(e) = tui::run(&parquet_data, path) {
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    }
                }
                Err(e) => {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    }
}

fn print_help() {
    println!("Command line tool to visualize parquet files");
    println!();
    println!("Usage: executable <PATH>");
    println!();
    println!("Arguments:");
    println!("  <PATH>  Path to the parquet file");
    println!();
    println!("Options:");
    println!("  -h, --help     Print help");
    println!("  -V, --version  Print version");
}
