use std::path::Path;
use anyhow::Result;
use arrow::array::RecordBatch;
use parquet::file::reader::SerializedFileReader;
use std::fs::File;

pub struct ParquetData {
    pub batches: Vec<RecordBatch>,
    pub file_metadata: FileMetadata,
    pub row_group_metadatas: Vec<RowGroupMetadata>,
}

pub struct FileMetadata {
    pub created_by: String,
    pub num_rows: i64,
    pub num_columns: usize,
    pub num_row_groups: usize,
    pub version: i32,
    pub raw_size: u64,
    pub compressed_size: u64,
}

pub struct RowGroupMetadata {
    pub index: usize,
    pub num_rows: i64,
    pub total_byte_size: u64,
    pub compressed_byte_size: u64,
}

pub fn read_parquet(path: &Path) -> Result<ParquetData> {
    let file = File::open(path)?;
    let reader = SerializedFileReader::new(file)?;

    let parquet_metadata = reader.metadata();
    let file_meta = parquet_metadata.file_metadata();

    let created_by = file_meta
        .created_by()
        .map(|s| s.to_string())
        .unwrap_or_else(|| "Unknown".to_string());

    let num_rows = file_meta.num_rows();
    let num_columns = file_meta.num_columns();
    let num_row_groups = parquet_metadata.num_row_groups();

    let version = file_meta.version() as i32;

    let mut raw_size = 0u64;
    let mut compressed_size = 0u64;

    let mut row_group_metadatas = Vec::new();

    for i in 0..num_row_groups {
        let rg_meta = parquet_metadata.row_group(i);
        let mut total_byte_size = 0u64;
        let mut compressed_byte_size = 0u64;

        for j in 0..rg_meta.num_columns() {
            let col_meta = rg_meta.column(j);
            total_byte_size += col_meta.total_uncompressed_size() as u64;
            compressed_byte_size += col_meta.total_compressed_size() as u64;
        }

        raw_size += total_byte_size;
        compressed_size += compressed_byte_size;

        row_group_metadatas.push(RowGroupMetadata {
            index: i,
            num_rows: rg_meta.num_rows(),
            total_byte_size,
            compressed_byte_size,
        });
    }

    let schema = reader.schema()?;
    let mut batches = Vec::new();

    for i in 0..num_row_groups {
        let row_group_reader = reader.get_row_group(i)?;
        let batch = arrow::io::parquet::read::read_row_group(
            row_group_reader,
            0,
            schema.clone(),
            None,
        )?;
        batches.push(batch);
    }

    Ok(ParquetData {
        batches,
        file_metadata: FileMetadata {
            created_by,
            num_rows,
            num_columns,
            num_row_groups,
            version,
            raw_size,
            compressed_size,
        },
        row_group_metadatas,
    })
}
