fn format_array_value(col: &arrow::array::ArrayRef, idx: usize) -> String {
    use arrow::array::{Array, BooleanArray, Int32Array, Int64Array, Float32Array, Float64Array, StringArray, BinaryArray};

    if idx >= col.len() {
        return String::new();
    }

    if col.is_null(idx) {
