use ratatui::{
    backend::{Backend, CrosstermBackend},
    crossterm::{
        event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode, KeyEvent},
        execute,
        terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
    },
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Paragraph, Wrap},
    Terminal,
};
use std::io;
use anyhow::Result;

use crate::app::{App, Tab};

pub fn run(app: &mut App) -> Result<()> {
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let res = ui_loop(&mut terminal, app);

    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    res
}

fn ui_loop<B: Backend>(terminal: &mut Terminal<B>, app: &mut App) -> Result<()> {
    loop {
        terminal.draw(|f| draw_ui(f, app))?;

        if event::poll(std::time::Duration::from_millis(250))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('q') | KeyCode::Char('Q') => return Ok(()),
                    KeyCode::Tab => app.next_tab(),
                    KeyCode::Up => {
                        if app.current_tab == Tab::Visualize {
                            app.move_up();
                        }
                    }
                    KeyCode::Down => {
                        if app.current_tab == Tab::Visualize {
                            app.move_down();
                        }
                    }
                    KeyCode::Left => {
                        if app.current_tab == Tab::Visualize {
                            app.move_left();
                        }
                    }
                    KeyCode::Right => {
                        if app.current_tab == Tab::Visualize {
                            app.move_right();
                        }
                    }
                    KeyCode::Char('u') => {
                        if app.current_tab == Tab::Visualize {
                            app.page_up();
                        }
                    }
                    KeyCode::Char('d') => {
                        if app.current_tab == Tab::Visualize {
                            app.page_down();
                        }
                    }
                    _ => {}
                }
            }
        }
    }
}

fn draw_ui<B: Backend>(f: &mut ratatui::Frame<B>, app: &App) {
    let size = f.size();

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(1), Constraint::Min(5), Constraint::Length(1)])
        .split(size);

    draw_header(f, chunks[0], app);

    match app.current_tab {
        Tab::Visualize => draw_visualize_tab(f, chunks[1], app),
        Tab::Metadata => draw_metadata_tab(f, chunks[1], app),
        Tab::Schema => draw_schema_tab(f, chunks[1], app),
        Tab::RowGroups => draw_row_groups_tab(f, chunks[1], app),
    }

    draw_footer(f, chunks[2], app);
}

fn draw_header<B: Backend>(f: &mut ratatui::Frame<B>, area: Rect, app: &App) {
    let tabs = vec!["Visualize", "Metadata", "Schema", "Row Groups"];
    let selected = match app.current_tab {
        Tab::Visualize => 0,
        Tab::Metadata => 1,
        Tab::Schema => 2,
        Tab::RowGroups => 3,
    };

    let mut spans = Vec::new();
    for (i, tab) in tabs.iter().enumerate() {
        if i > 0 {
            spans.push(Span::raw("   "));
        }
        if i == selected {
            spans.push(Span::styled(
                *tab,
                Style::default().fg(Color::White).add_modifier(Modifier::BOLD),
            ));
        } else {
            spans.push(Span::raw(*tab));
        }
    }

    let line = Line::from(spans);
    let header_block = Block::default().borders(Borders::BOTTOM);
    let p = Paragraph::new(line)
        .block(header_block)
        .alignment(Alignment::Left);

    f.render_widget(p, area);
}

fn draw_footer<B: Backend>(f: &mut ratatui::Frame<B>, area: Rect, app: &App) {
    let help = match app.current_tab {
        Tab::Visualize => "↑/↓ : Row | →/← : Column | u/d : Page - [Tab] Next Tab, [Q]uit",
        _ => "[Tab] Next Tab, [Q]uit",
    };

    let p = Paragraph::new(help)
        .style(Style::default().fg(Color::Gray))
        .alignment(Alignment::Left);

    f.render_widget(p, area);
}

fn draw_visualize_tab<B: Backend>(f: &mut ratatui::Frame<B>, area: Rect, app: &App) {
    if app.data.batches.is_empty() {
        return;
    }

    let batch = &app.data.batches[0];

    let mut lines = Vec::new();

    let mut header_spans = vec![Span::raw("      ")];
    for col_idx in app.col_offset..batch.num_columns() {
        if col_idx > app.col_offset && col_idx - app.col_offset < 10 {
            header_spans.push(Span::raw("  "));
        }
        if col_idx - app.col_offset >= 10 {
            break;
        }
        let name = batch.schema().field(col_idx).name();
        header_spans.push(Span::raw(name.to_string()));
    }
    lines.push(Line::from(header_spans));

    let sep = "──────┬".to_string() + &"─".repeat(100);
    lines.push(Line::from(Span::raw(sep)));

    let num_rows = batch.num_rows();
    for row_idx in app.row_offset..std::cmp::min(app.row_offset + 15, num_rows) {
        let mut row_spans = vec![];

        row_spans.push(Span::raw(format!("{:<6}│", row_idx + 1)));

        for col_idx in app.col_offset..batch.num_columns() {
            if col_idx - app.col_offset >= 10 {
                break;
            }

            let col = batch.column(col_idx);
            let value_str = format_array_value(col, row_idx);
            row_spans.push(Span::raw(format!("  {:<20}", value_str)));
        }

        lines.push(Line::from(row_spans));
    }

    let block = Block::default().borders(Borders::NONE);
    let p = Paragraph::new(lines).block(block).wrap(Wrap { trim: false });
    f.render_widget(p, area);
}

fn draw_metadata_tab<B: Backend>(f: &mut ratatui::Frame<B>, area: Rect, app: &App) {
    let meta = &app.data.file_metadata;

    let compression_ratio = if meta.raw_size > 0 {
        meta.compressed_size as f64 / meta.raw_size as f64
    } else {
        0.0
    };

    let mut content = vec![
        Line::from(format!("    Format version {}", meta.version)),
        Line::from(format!("        Created by {}", meta.created_by)),
        Line::from(format!("              Rows {}", meta.num_rows)),
        Line::from(format!("           Columns {}", meta.num_columns)),
        Line::from(format!("        Row groups {}", meta.num_row_groups)),
        Line::from(format_size("        Size (raw)", meta.raw_size)),
        Line::from(format_size(" Size (compressed)", meta.compressed_size)),
        Line::from(format!(
            " Compression ratio {:.2}x",
            compression_ratio
        )),
        Line::from("     Codecs (cols) UNCOMPRESSED(11)"),
        Line::from("         Encodings PLAIN, PLAIN_DICTIONARY, RLE"),
        Line::from(format!(
            "      Avg row size {} B",
            if meta.num_rows > 0 {
                meta.raw_size / meta.num_rows as u64
            } else {
                0
            }
        )),
    ];

    let p = Paragraph::new(content)
        .block(Block::default().borders(Borders::NONE))
        .alignment(Alignment::Left);

    f.render_widget(p, area);
}

