pub struct ParquetData {
    pub rows: Vec<Vec<String>>,
    pub columns: Vec<String>,
    pub metadata: FileMetadata,
    pub raw_data: Vec<u8>,
}

pub struct FileMetadata {
    pub created_by: String,
    pub num_rows: i64,
    pub num_columns: usize,
    pub num_row_groups: usize,
    pub version: i32,
    pub raw_size: u64,
    pub compressed_size: u64,
}

pub fn parse(data: &[u8]) -> Result<ParquetData, String> {
    if data.len() < 12 {
        return Err("Invalid parquet file: too small".to_string());
    }

    // Check magic number at start
    if &data[0..4] != b"PAR1" {
        return Err("Invalid parquet file: missing PAR1 header".to_string());
    }

    // Check magic number at end  
    if &data[data.len()-4..] != b"PAR1" {
        return Err("Invalid parquet file: missing PAR1 footer".to_string());
    }

    // Parse footer metadata size (4 bytes before the final PAR1)
    let footer_size_pos = data.len() - 8;
    let footer_size = u32::from_le_bytes([
        data[footer_size_pos],
        data[footer_size_pos + 1],
        data[footer_size_pos + 2],
        data[footer_size_pos + 3],
    ]) as usize;

    if footer_size > data.len() - 8 {
        return Err("Invalid footer size".to_string());
    }

    let metadata_start = data.len() - 8 - footer_size;

    // Try to extract some basic information from metadata
    // Look for column names by scanning for UTF-8 strings
    let mut columns = Vec::new();
    let mut rows = Vec::new();
    let num_rows = 0i64;

    // Scan metadata section for reasonable-looking column names
    if metadata_start < data.len() {
        let metadata_section = &data[4..metadata_start];
        let mut i = 0;
        while i < metadata_section.len().saturating_sub(20) {
            if let Some((name, len)) = try_extract_string(&metadata_section[i..]) {
                if name.len() > 1 && name.len() < 100 && is_valid_column_name(&name) {
                    // Check if we already have this name
                    if !columns.contains(&name) {
                        columns.push(name);
                    }
                }
                i += len + 1;
            } else {
                i += 1;
            }
        }
    }

    // Default column if no columns found
    if columns.is_empty() {
        columns.push("column".to_string());
    }

    let num_columns = columns.len();

    Ok(ParquetData {
        rows,
        columns,
        metadata: FileMetadata {
            created_by: String::new(),
            num_rows,
            num_columns,
            num_row_groups: 1,
            version: 1,
            raw_size: data.len() as u64,
            compressed_size: data.len() as u64,
        },
        raw_data: data.to_vec(),
    })
}

fn try_extract_string(data: &[u8]) -> Option<(String, usize)> {
    if data.is_empty() || data.len() < 2 {
        return None;
    }

    // Try to extract a null-terminated string
    for i in 1..data.len().min(256) {
        if data[i] == 0 {
            if let Ok(s) = String::from_utf8(data[..i].to_vec()) {
                if s.len() > 0 && s.len() < 100 && s.chars().all(|c| c.is_ascii()) {
                    return Some((s, i));
                }
            }
            return None;
        }
    }

    None
}

fn is_valid_column_name(name: &str) -> bool {
    name.chars().all(|c| {
        c.is_ascii_alphanumeric() || c == '_' || c == '-'
    }) && name.chars().next().map(|c| c.is_ascii_alphabetic() || c == '_').unwrap_or(false)
}
