    }

    let metadata_start = data.len() - 8 - footer_size;

    // Extract column names from the file
    let mut columns = extract_column_names(data);

    if columns.is_empty() {
        columns.push("column".to_string());
    }

    let num_columns = columns.len();

    Ok(ParquetData {
