        columns,
        metadata: FileMetadata {
            created_by: String::new(),
            num_rows: 0,
            num_columns,
            num_row_groups: 1,
            version: 1,
            raw_size: data.len() as u64,
            compressed_size: data.len() as u64,
        },
        raw_data: data.to_vec(),
    })
}

fn extract_column_names(data: &[u8]) -> Vec<String> {
    let mut names = Vec::new();
    let mut i = 0;
    let max_len = 256; // Column names shouldn't be longer than this
    let mut seen = std::collections::HashSet::new();

    while i < data.len().saturating_sub(5) {
        // Look for patterns that are likely column names
        // They appear after specific markers in parquet files
        if i > 0 && data[i - 1] == 0 {
            // Previous byte was null terminator, check if current position has a valid name
            if let Some(len) = extract_name_at(data, i, &mut seen) {
                i += len;
                continue;
            }
        }
        i += 1;
    }

    names
}

fn extract_name_at(data: &[u8], start: usize, seen: &mut std::collections::HashSet<String>) -> Option<usize> {
    if start >= data.len() {
        return None;
    }

    // Find the next null byte
    let mut end = start;
    while end < data.len() && end < start + 256 {
        if data[end] == 0 {
            break;
        }
        end += 1;
    }

    if end <= start || end >= data.len() {
        return None;
    }

    // Try to decode as UTF-8
    if let Ok(s) = String::from_utf8(data[start..end].to_vec()) {
        // Check if it looks like a valid column name
        if is_valid_column_name(&s) && !seen.contains(&s) {
            seen.insert(s);
            return Some(end - start + 1);
        }
    }

    None
}

fn is_valid_column_name(name: &str) -> bool {
    if name.is_empty() || name.len() > 100 {
        return false;
    }

    // Column names should contain mostly alphanumeric, underscore, and dash
    let mut valid_chars = 0;
    let mut special_chars = 0;
    let mut control_chars = 0;

    for c in name.chars() {
        if c.is_ascii_alphanumeric() || c == '_' || c == '-' {
            valid_chars += 1;
        } else if c == ' ' {
            special_chars += 1;
        } else if c.is_ascii_control() {
            control_chars += 1;
            return false;
        } else {
            // Allow some other chars but be restrictive
            if !c.is_ascii() {
                return false;
            }
        }
    }

    // Must be mostly valid alphanumeric characters
    valid_chars + special_chars > name.len() / 2
}
