use std::collections::HashSet;

pub struct ParquetData {
    pub rows: Vec<Vec<String>>,
    pub columns: Vec<String>,
    pub metadata: FileMetadata,
    pub raw_data: Vec<u8>,
}

pub struct FileMetadata {
    pub created_by: String,
    pub num_rows: i64,
    pub num_columns: usize,
    pub num_row_groups: usize,
    pub version: i32,
    pub raw_size: u64,
    pub compressed_size: u64,
}

pub fn parse(data: &[u8]) -> Result<ParquetData, String> {
    if data.len() < 12 {
        return Err("Invalid parquet file: too small".to_string());
    }

    // Check magic number at start
    if &data[0..4] != b"PAR1" {
        return Err("Invalid parquet file: missing PAR1 header".to_string());
    }

    // Check magic number at end  
    if &data[data.len()-4..] != b"PAR1" {
        return Err("Invalid parquet file: missing PAR1 footer".to_string());
    }

    // Parse footer metadata size (4 bytes before the final PAR1)
    let footer_size_pos = data.len() - 8;
    let _footer_size = u32::from_le_bytes([
        data[footer_size_pos],
        data[footer_size_pos + 1],
        data[footer_size_pos + 2],
        data[footer_size_pos + 3],
    ]) as usize;

    // Extract column names
    let columns = extract_column_names(data);
    let num_columns = columns.len();

    Ok(ParquetData {
        rows: Vec::new(),
        columns,
        metadata: FileMetadata {
            created_by: String::new(),
            num_rows: 0,
            num_columns,
            num_row_groups: 1,
            version: 1,
            raw_size: data.len() as u64,
            compressed_size: data.len() as u64,
        },
        raw_data: data.to_vec(),
    })
}

fn extract_column_names(data: &[u8]) -> Vec<String> {
    let mut names = Vec::new();
    let mut seen = HashSet::new();

    let mut i = 0;
    while i < data.len().saturating_sub(4) {
        // Look for the pattern 0x18 followed by a length byte and then ascii characters
        if data[i] == 0x18 && i + 1 < data.len() {
            let len = data[i + 1] as usize;

            // Length should be reasonable for a column name
            if len > 0 && len < 256 && i + 2 + len <= data.len() {
                let candidate = &data[i + 2..i + 2 + len];

                // Try to decode as UTF-8 and check if it's a valid column name
                if let Ok(name) = String::from_utf8(candidate.to_vec()) {
                    if is_valid_column_name(&name) && !seen.contains(&name) {
                        names.push(name.clone());
                        seen.insert(name);
                        i += len;
                        continue;
                    }
                }
            }
        }
        i += 1;
    }

    // If still no names found, try a fallback: look for any printable ASCII strings
    if names.is_empty() {
        names = extract_column_names_fallback(data, &mut seen);
    }

    if names.is_empty() {
        names.push("column".to_string());
    }

    names
}

fn extract_column_names_fallback(data: &[u8], seen: &mut HashSet<String>) -> Vec<String> {
    let mut names = Vec::new();
    let mut i = 0;

    while i < data.len().saturating_sub(2) {
        // Look for potential names preceded by null byte
        if i > 0 && data[i - 1] == 0 && data[i].is_ascii_alphabetic() {
            let start = i;
            let mut end = i;

            while end < data.len() && end < start + 100 && (data[end].is_ascii_alphanumeric() || data[end] == b'_' || data[end] == b'-') {
                end += 1;
            }

            if end > start + 1 && end < data.len() && data[end] == 0 {
                let name = String::from_utf8_lossy(&data[start..end]).to_string();
                if is_valid_column_name(&name) && !seen.contains(&name) {
                    names.push(name.clone());
                    seen.insert(name);
                    i = end;
                    continue;
                }
            }
        }
        i += 1;
    }

    names
}

fn is_valid_column_name(name: &str) -> bool {
    if name.is_empty() || name.len() > 100 {
        return false;
    }

    // Column names should start with letter or underscore
    if !name.chars().next().map(|c| c.is_ascii_alphabetic() || c == '_').unwrap_or(false) {
        return false;
    }

    // All characters should be alphanumeric, underscore, or dash
    name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
}
